	dgeqrf( 'column-major', null, 4, A, 3, TAU, WORK, 4 ); // $ExpectError
	dgeqrf( 'column-major', undefined, 4, A, 3, TAU, WORK, 4 ); // $ExpectError
	dgeqrf( 'column-major', [], 4, A, 3, TAU, WORK, 4 ); // $ExpectError
